#include <stdio.h>

double average(const int *values, int count);

int main(void) {
    int n;
    scanf("%d", &n);
    int values[100];
    for (int i = 0; i < n; i++) {
        scanf("%d", &values[i]);
    }
    printf("%.2f\n", average(values, n));
    return 0;
}

double average(const int *values, int count) {
    long long sum = 0;
    for (int i = 0; i < count; i++) {
        sum += values[i];
    }
    return (double)sum / count;
}
